//! Option form follows the qualifying ancestor SELECT owner.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=owner><select id=select><option id=option>One</option><optgroup><option id=grouped>Two</option></optgroup></select><datalist id=choices><option id=suggestion>Suggestion</option></datalist></form><form id=other></form><select id=external form=other><option id=externalOption>External</option></select><select id=missing form=missing><option id=missingOption>Missing</option></select><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://option-form.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn option_form_canonical_readonly_descriptor_and_actual_native_owner(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),owner=document.getElementById('owner'),a=Object.getOwnPropertyDescriptor(HTMLOptionElement.prototype,'form');if(!a||!a.enumerable||!a.configurable||a.set!==undefined||a.get.length!==0||a.get.name!=='get form'||Object.hasOwn(x,'form')||x.form!==owner||a.get.call(x)!==owner||document.getElementById('grouped').form!==owner)throw 'canonical option form';var calls=0;x.form={toString:function(){calls++;return 'other';}};if(x.form!==owner||calls)throw 'sloppy readonly';var caught=false;try{(function(){'use strict';x.form=null;})();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'strict readonly';"#);}
#[test]
fn option_form_actual_select_explicit_owner_and_no_option_attribute_override(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('externalOption'),select=document.getElementById('external'),other=document.getElementById('other');if(x.form!==other||x.form!==select.form||document.getElementById('missingOption').form!==null)throw 'parsed explicit select owner';if(x.form!==other)throw 'option attribute has no owner authority';"#);}

#[test]
fn option_form_standalone_datalist_and_inert_namespace_owner(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"if(document.createElement('option').form!==null||document.getElementById('suggestion').form!==null)throw 'no select means no form';var doc=document.implementation.createHTMLDocument('inert'),html='http://www.w3.org/1999/xhtml',owner=doc.createElement('form'),select=doc.createElement('select'),x=doc.createElementNS(html,'p:option');doc.body.appendChild(owner);owner.appendChild(select);select.appendChild(x);if(x.form!==owner||x.form!==select.form||x.ownerDocument!==doc)throw 'inert actual owner';var alone=doc.createElement('option');owner.appendChild(alone);if(alone.form!==null)throw 'form ancestor alone insufficient';"#);}
#[test]
fn option_form_brand_author_override_and_saved_constructor(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),C=HTMLOptionElement,P=C.prototype,get=Object.getOwnPropertyDescriptor(P,'form').get;for(var bad of [{},Object.create(P),document.body,document.createElement('select'),document.createElementNS('urn:foreign','option'),new Document().createElementNS('http://www.w3.org/1999/xhtml','OPTION')]){var caught=false;try{get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'form concrete brand';}Object.defineProperty(x,'form',{value:'author',configurable:true});if(x.form!=='author'||get.call(x)!==document.getElementById('owner'))throw 'canonical authority';delete x.form;delete window.HTMLOptionElement;if(!(x instanceof C)||get.call(x)!==document.getElementById('owner'))throw 'saved constructor';"#);}

#[test]
fn option_form_ancestry_boundaries_follow_exact_html_tree(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),html='http://www.w3.org/1999/xhtml',owner=doc.createElementNS(html,'form'),select=doc.createElementNS(html,'select');owner.appendChild(select);function make(parent,tag,ns){var x=doc.createElementNS(ns===undefined?html:ns,tag);parent.appendChild(x);return x;}var plain=make(make(select,'div'),'option'),group=make(select,'optgroup'),one=make(make(group,'div'),'option'),two=make(make(group,'optgroup'),'option'),list=make(make(select,'datalist'),'option'),rule=make(make(select,'hr'),'option'),nested=make(make(select,'option'),'option'),foreign=make(make(select,'datalist','urn:foreign'),'option');for(var x of [plain,one,foreign])if(x.form!==owner)throw 'qualifying ancestor';for(var x of [two,list,rule,nested])if(x.form!==null)throw 'blocked ancestor';"#);}

#[test]
fn option_form_native_work_deadline_and_allocation_free_reads_recover(){for mode in 0..3{let(mut d,mut f,mut p)=fixture();let n=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("option")).unwrap();let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("owner")).unwrap();p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.execution_deadline=Some(Instant::now()),_=>{p.state.copy_work=0;p.state.retained_limit=p.state.retained;p.state.limits.host.string_bytes=0;}}let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.option_form_get(node_handle(n));if mode==2{assert!(matches!(result,Ok(Value::Host(actual))if actual==node_handle(owner)));}else{let e=result.unwrap_err();assert!(e.contains("work")||e.contains("time"),"{e}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();assert!(matches!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.option_form_get(node_handle(n)).unwrap(),Value::Host(actual)if actual==node_handle(owner)));}}
#[test]
fn option_form_saved_child_origin_precedes_reads_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('option'),owner=document.getElementById('owner'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var get=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLOptionElement.prototype,'form').get;if(get.call(x)!==owner)throw 'same origin owner';");p.set_location(&crate::navigation::address("https://other-option-form.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits);p.begin_job();let e=p.runtime.execute("get.call(x);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),state);p.set_location(&crate::navigation::address("https://option-form.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(get.call(x)!==owner)throw 'saved owner recovery';");}
#[test]
fn option_form_inert_live_explicit_owner_exact_ids_and_refusal_recovery(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),html='http://www.w3.org/1999/xhtml',root=doc.createElementNS(html,'div'),owner=doc.createElementNS(html,'form'),other=doc.createElementNS(html,'form'),select=doc.createElementNS(html,'select'),x=doc.createElementNS(html,'option');doc.appendChild(root);root.appendChild(owner);root.appendChild(other);owner.appendChild(select);select.appendChild(x);other.id='A\ud800z';select.setAttribute('form','A\ud800z');x.setAttribute('form','ignored');var watch=new MutationObserver(function(){});watch.observe(root,{attributes:true,subtree:true,childList:true});if(x.form!==other)throw 'inert explicit owner';select.setAttribute('form','A\ufffdz');if(x.form!==null)throw 'exact owner no scalar alias';select.removeAttribute('form');if(x.form!==owner)throw 'ancestor recovery';select.setAttribute('form','A\ud800z');watch.takeRecords();"#);let limit=p.state.retained_limit;for mode in 0..4{let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.execution_deadline=Some(Instant::now()),2=>p.state.copy_work=0,_=>p.state.retained_limit=p.state.retained};let e=p.runtime.execute("x.form;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("time"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(x.form!==other||watch.takeRecords().length)throw 'fresh inert owner recovery';");}}
#[test]
fn option_form_preserves_native_select_reassociation_guard(){let(mut d,mut f,mut p)=fixture();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits);p.begin_job();let e=p.runtime.execute("document.getElementById('select').setAttribute('form','other');",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("form")||e.contains("Supported attributes"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),state);p.begin_job();run(&mut d,&mut f,&mut p,"if(document.getElementById('option').form!==document.getElementById('owner'))throw 'owner after refusal';");}
